import static org.jlinalg.cli.FollowupSupport.*;

/** Typed original region matrices, figures and alignment-summary correlations. */
final class DeepToolsMatrixCli {
    private DeepToolsMatrixCli() { }
    static final Set<String> METHODS=Set.of("matrix","plot-profile","plot-heatmap","bam-summary","correlation");
    private static final Set<String> COMMON=Set.of("method","out","runtime-home","timeout","max-cells","max-bytes");
    private static final Set<String> REFERENCE=Set.of("samples","sizes","sizes-format","genome-build");
    private static final Set<String> MATRIX=Set.of("regions","group-label","mode","bin-size","upstream","downstream","body-length","reference-point","missing","skip-zero-rows","bin-average","nan-after-end");
    private static final Set<String> SUMMARY=Set.of("mode","regions","bin-size","distance-between-bins","max-records","min-mapq","sam-include","sam-exclude","ignore-duplicates","min-fragment-length","max-fragment-length","extend-reads");
    private static final Set<String> PLOT=Set.of("model","format","dpi","average","plot-type","per-group","sort-regions","sort-using","color-map","plot-title");
    private static final Set<String> CORRELATION=Set.of("model","format","correlation-method","what-to-plot","zero-rows","color-map","plot-title");
    private record Sample(String id,Path path) { }

    static int run(String[] args,PrintStream out,PrintStream err) {
        try {
            var allowed=new HashSet<>(COMMON);allowed.addAll(REFERENCE);allowed.addAll(MATRIX);allowed.addAll(SUMMARY);allowed.addAll(PLOT);allowed.addAll(CORRELATION);var options=options(args,allowed);
            String method=required(options,"method");if(!METHODS.contains(method))throw new IOException("Unknown matrix/plot/summary deepTools method:"+method);
            boolean producer=Set.of("matrix","bam-summary").contains(method);var applicable=new HashSet<>(COMMON);
            if(producer){applicable.addAll(REFERENCE);applicable.addAll(method.equals("matrix")?MATRIX:SUMMARY);}else applicable.addAll(method.equals("correlation")?CORRELATION:PLOT);
            for(String key:options.keySet())if(!applicable.contains(key))throw new IOException("--"+key+" does not apply to "+method);
            int timeout=integer(options,"timeout",3600,1,86400);long maxCells=integer(options,"max-cells",10_000_000,1,100_000_000),maxBytes=(long)integer(options,"max-bytes",268_435_456,1024,2_000_000_000);
            if(producer){for(String key:List.of("samples","sizes","genome-build"))required(options,key);choice(options,"sizes-format","sizes","sizes","fai");}
            if(method.equals("matrix"))validateMatrix(options);
            else if(method.equals("bam-summary"))validateSummary(options);
            else {
                required(options,"model");choice(options,"format","png","png","pdf","svg");integer(options,"dpi",100,40,300);text(options.getOrDefault("plot-title",""),"plot-title",500);
                choice(options,"color-map","viridis","viridis","plasma","magma","inferno","cividis","RdBu_r","Greys");
                if(method.equals("correlation")){choiceRequired(options,"correlation-method","pearson","spearman");choiceRequired(options,"what-to-plot","heatmap","scatterplot");choiceRequired(options,"zero-rows","keep","omit");}
                else{choiceRequired(options,"average","mean","median","min","max","std","sum");bool(options,"per-group",false);if(method.equals("plot-profile")){choice(options,"plot-type","lines","lines","fill","se","std","overlapped_lines","heatmap");for(String key:List.of("sort-regions","sort-using","color-map"))if(options.containsKey(key))throw new IOException("--"+key+" does not apply to plot-profile");}else{if(options.containsKey("plot-type"))throw new IOException("plot-type applies only to plot-profile");choice(options,"sort-regions","keep","keep","ascend","descend");choice(options,"sort-using","mean","mean","median","min","max","sum","region_length");}}
            }
            String runtime=options.getOrDefault("runtime-home",System.getenv("JLINALG_DEEPTOOLS_HOME"));int[] code={0};
            externalTransaction(options,"deep-tools-"+method,(directory,manifest)->{
                var session=new LinkedHashMap<String,Object>();var warnings=new ArrayList<String>();var sources=new LinkedHashMap<Path,String>();session.put("method",method);session.put("engine","original-deepTools-3.5.6");
                try {
                    if(runtime==null||runtime.isBlank())throw new DeepToolsRuntime.Unavailable("Supply --runtime-home or JLINALG_DEEPTOOLS_HOME with a matching sealed deepTools3.5.6 profile",null);
                    var original=new DeepToolsRuntime(Path.of(runtime),directory,session);
                    if(producer){
                        Path sizes=source(options.get("sizes"),sources,maxBytes);var reference=GenomicSignalCli.reference(sizes,options.getOrDefault("sizes-format","sizes"));if(reference.isEmpty()||reference.values().stream().anyMatch(value->value>Integer.MAX_VALUE))throw new IOException("Require a nonempty ordered reference within signed-32-bit contig bounds");
                        List<Sample> samples=samples(source(options.get("samples"),sources,maxBytes),sources,method.equals("matrix")?maxBytes:Long.MAX_VALUE);session.put("genome_build_declared",options.get("genome-build"));
                        try(var writer=Files.newBufferedWriter(directory.resolve("reference.sizes"))){for(var entry:reference.entrySet())writer.write(entry.getKey()+"\t"+entry.getValue()+"\n");}
                        try(var writer=Files.newBufferedWriter(directory.resolve("samples.tsv"))){writer.write("sample\tpath\n");for(var sample:samples)writer.write(sample.id()+"\t"+sample.path()+"\n");}
                        if(method.equals("matrix"))matrix(original,directory,options,reference,samples,sources,maxCells,maxBytes,timeout,session,warnings);
                        else summary(original,directory,options,reference,samples,sources,maxCells,maxBytes,timeout,session,warnings);
                    }else plot(original,directory,options,method,sources,maxCells,maxBytes,timeout,session,warnings);
                    RegenieRuntime.verify(sources);original.verify();warnings.addAll(warnings(directory));manifest.put("analysis_status",warnings.isEmpty()?"completed":"completed-with-warnings");
                }catch(DeepToolsRuntime.Unavailable unavailable){code[0]=3;manifest.put("analysis_status","skipped-dependency");manifest.put("error",unavailable.getMessage());RnaToolRuntime.quarantine(directory);warnings.add(0,"ANALYSIS SKIPPED - DEPENDENCY:"+unavailable.getMessage());}
                catch(Exception failure){code[0]=2;manifest.put("analysis_status","failed");manifest.put("error",String.valueOf(failure.getMessage()));RnaToolRuntime.quarantine(directory);warnings.add(0,"ANALYSIS FAILED:"+failure.getMessage());}
                session.put("source_sha256",sources.entrySet().stream().collect(java.util.stream.Collectors.toMap(entry->entry.getKey().toString(),Map.Entry::getValue)));session.put("warnings",warnings);Files.writeString(directory.resolve("session.yaml"),new org.yaml.snakeyaml.Yaml().dump(session));Files.writeString(directory.resolve("analysis-status.json"),RegenieRuntime.json(Map.of("status",manifest.get("analysis_status")))+"\n");
                if(!warnings.isEmpty())Files.writeString(directory.resolve("WARNINGS.md"),"# "+(code[0]==3?"ANALYSIS SKIPPED - DEPENDENCY REQUIRED":code[0]==2?"ANALYSIS FAILED":"DEEPTOOLS MATRIX/PLOT WARNINGS REQUIRE REVIEW")+"\n\n"+String.join("\n\n",warnings)+"\n\nRequired action:"+(code[0]==3?DeepToolsUpstreamCli.setup():code[0]==2?"Inspect retained stage logs and completion markers under partial/. Correct the named reference,labels,regions,missingness,model,constant-column or resource issue; rerun to a NEW output directory. No successful result is published.":"Review the signal/count units,region omissions,missing values,zero-row policy,model/source identities and figure data before downstream interpretation. A figure is not an independent association or causal test.")+"\n");
            });
            if(Files.exists(Path.of(options.get("out"),"WARNINGS.md")))err.println((code[0]==3?"ANALYSIS SKIPPED - DEPENDENCY REQUIRED: ":code[0]==2?"ANALYSIS FAILED: ":"DEEPTOOLS MATRIX/PLOT WARNINGS REQUIRE REVIEW: ")+Path.of(options.get("out"),"WARNINGS.md"));if(code[0]==0)out.println("Original deepTools "+method+" completed:"+options.get("out"));return code[0];
        }catch(Exception failure){err.println("jlinalg:"+failure.getMessage());return 2;}
    }
    private static void validateMatrix(Map<String,String> options)throws IOException {
        required(options,"regions");id(required(options,"group-label"),"group-label");String mode=choiceRequired(options,"mode","reference-point","scale-regions");int bin=positive(options,"bin-size"),up=nonnegative(options,"upstream"),down=nonnegative(options,"downstream"),body=0;
        if(mode.equals("scale-regions")){body=positive(options,"body-length");if(options.containsKey("reference-point"))throw new IOException("reference-point does not apply to scale-regions");}else{choiceRequired(options,"reference-point","TSS","TES","center");if(options.containsKey("body-length"))throw new IOException("body-length applies only to scale-regions");}
        if(up%bin!=0||down%bin!=0||body%bin!=0||(long)up+down+body<bin)throw new IOException("Flanks/body must be exact bin-size multiples and supply at least one bin");
        choiceRequired(options,"missing","zero","retain","error");choiceRequired(options,"bin-average","mean","median","min","max","std","sum");required(options,"skip-zero-rows");bool(options,"skip-zero-rows",false);bool(options,"nan-after-end",false);
    }
    private static void validateSummary(Map<String,String> options)throws IOException {
        String mode=choiceRequired(options,"mode","bins","regions");if(mode.equals("bins")){positive(options,"bin-size");integer(options,"distance-between-bins",0,0,Integer.MAX_VALUE);if(options.containsKey("regions"))throw new IOException("regions applies only to summary mode regions");}else{required(options,"regions");if(options.containsKey("bin-size")||options.containsKey("distance-between-bins"))throw new IOException("bin-size/distance-between-bins apply only to summary bins");}
        integer(options,"max-records",10_000_000,1,1_000_000_000);integer(options,"min-mapq",0,0,255);integer(options,"sam-include",0,0,65535);integer(options,"sam-exclude",0,0,65535);bool(options,"ignore-duplicates",false);int min=integer(options,"min-fragment-length",0,0,Integer.MAX_VALUE),max=integer(options,"max-fragment-length",0,0,Integer.MAX_VALUE);if(max!=0&&max<min)throw new IOException("max-fragment-length must be zero or at least min-fragment-length");if(options.containsKey("extend-reads"))integer(options,"extend-reads",1,1,2000);
    }
    private static void matrix(DeepToolsRuntime runtime,Path directory,Map<String,String> options,Map<String,Long> reference,List<Sample> samples,Map<Path,String> sources,long maxCells,long maxBytes,int timeout,Map<String,Object> session,List<String> warnings)throws Exception {
        Path input=source(options.get("regions"),sources,maxBytes);int rows=bed(input,reference);int bin=positive(options,"bin-size"),up=nonnegative(options,"upstream"),down=nonnegative(options,"downstream"),body=options.containsKey("body-length")?positive(options,"body-length"):0;long columns=((long)up+down+body)/bin;if(Math.multiplyExact(Math.multiplyExact(columns,rows),samples.size())>maxCells)throw new IOException("Region/sample/bin matrix exceeds max-cells; choose explicit flanks,binning or resource budget");
        String group=options.get("group-label");Files.createDirectory(directory.resolve("regions"));Path canonical=directory.resolve("regions/"+group+".bed");Files.copy(input,canonical);
        var arguments=new ArrayList<String>(List.of(options.get("mode"),"-R",runtime.path(canonical),"-S"));var labels=samples.stream().map(Sample::id).toList();int sampleIndex=0;
        for(var sample:samples){var request=audit("bigwig",runtime,sample.path(),reference,maxCells);request.put("missing","retain");session.put("sample_"+sample.id()+"_audit",runtime.audit(request,"track-audit-"+(sampleIndex++),timeout).get("audit"));arguments.add(runtime.path(sample.path()));}
        arguments.addAll(List.of("-o",runtime.path(directory.resolve("matrix.gz")),"--outFileNameMatrix",runtime.path(directory.resolve("values.tsv")),"--outFileSortedRegions",runtime.path(directory.resolve("matrix-regions.bed")),"--binSize",Integer.toString(bin),"-b",Integer.toString(up),"-a",Integer.toString(down),"--sortRegions","keep","--averageTypeBins",options.get("bin-average"),"--numberOfProcessors","1","--samplesLabel"));arguments.addAll(labels);
        if(body>0)arguments.addAll(List.of("--regionBodyLength",Integer.toString(body)));else arguments.addAll(List.of("--referencePoint",options.get("reference-point")));
        if(options.get("missing").equals("zero"))arguments.add("--missingDataAsZero");if(bool(options,"skip-zero-rows",false))arguments.add("--skipZeros");if(bool(options,"nan-after-end",false))arguments.add("--nanAfterEnd");
        runtime.run("computeMatrix",arguments,"compute-matrix",timeout);size(directory.resolve("matrix.gz"),maxBytes);size(directory.resolve("values.tsv"),maxBytes);
        var parameters=new LinkedHashMap<String,Object>();parameters.put("bin size",bin);parameters.put("upstream",up);parameters.put("downstream",down);parameters.put("body",body);parameters.put("ref point",options.get("reference-point"));
        var model=baseModel("matrix",options.get("genome-build"),labels);model.put("regions_file","regions/"+group+".bed");model.put("group_label",group);model.put("columns_per_sample",columns);model.put("parameters",parameters);model.put("missing",options.get("missing"));
        Map<String,Object> request=matrixAudit(runtime,directory,model,directory.resolve("matrix.gz"),canonical,maxCells);request.put("sorted_regions",runtime.path(directory.resolve("matrix-regions.bed")));request.put("sorted_keep",true);var result=runtime.audit(request,"matrix-audit",timeout);Files.copy(directory.resolve("region-status.tsv"),directory.resolve("results.tsv"));session.put("matrix_audit",result.get("audit"));model.put("matrix_audit",result.get("audit"));sealModel(directory,model,List.of("matrix.gz","reference.sizes","samples.tsv","regions/"+group+".bed","results.tsv","region-status.tsv","matrix-regions.bed","values.tsv"));
        warnings.add("MATRIX SIGNAL CONTRACT:BigWig values retain their supplied units; no counts or library normalization is inferred. Mode="+options.get("mode")+",bin-average="+options.get("bin-average")+",missing="+options.get("missing")+",skip-zero-rows="+options.get("skip-zero-rows")+",nan-after-end="+bool(options,"nan-after-end",false)+". Strand-aware BED6 order is audited. results.tsv lists EVERY input region as kept or omitted-by-original; inspect missing cells/omissions before interpreting a profile. Numeric matrix text uses original six-decimal output; source BigWig is float32.");
    }
    private static void summary(DeepToolsRuntime runtime,Path directory,Map<String,String> options,Map<String,Long> reference,List<Sample> samples,Map<Path,String> sources,long maxCells,long maxBytes,int timeout,Map<String,Object> session,List<String> warnings)throws Exception {
        boolean bins=options.get("mode").equals("bins");long rows=0;Path canonical=null;int bin=0;long step=0;
        if(bins){bin=positive(options,"bin-size");step=(long)bin+integer(options,"distance-between-bins",0,0,Integer.MAX_VALUE);for(long length:reference.values())rows=Math.addExact(rows,(length-1)/step+1);}else{Path input=source(options.get("regions"),sources,maxBytes);rows=bed(input,reference);Files.createDirectory(directory.resolve("regions"));canonical=directory.resolve("regions/regions.bed");Files.copy(input,canonical);}
        if(Math.multiplyExact(rows,samples.size())>maxCells)throw new IOException("Summary region/bin/sample matrix exceeds max-cells");
        var arguments=new ArrayList<String>(List.of(bins?"bins":"BED-file","-b"));int index=0;
        for(var sample:samples){indexes(sample.path(),sources,maxBytes);var request=audit("bam",runtime,sample.path(),reference,maxCells);request.put("max_records",integer(options,"max-records",10_000_000,1,1_000_000_000));session.put("sample_"+sample.id()+"_audit",runtime.audit(request,"bam-audit-"+(index++),timeout).get("audit"));arguments.add(runtime.path(sample.path()));}
        arguments.addAll(List.of("-o",runtime.path(directory.resolve("summary.npz")),"--outRawCounts",runtime.path(directory.resolve("original-counts.tsv")),"--numberOfProcessors","1"));
        if(bins)arguments.addAll(List.of("--binSize",Integer.toString(bin),"--distanceBetweenBins",options.getOrDefault("distance-between-bins","0")));else arguments.addAll(List.of("--BED",runtime.path(canonical)));
        for(var entry:Map.of("min-mapq","--minMappingQuality","sam-include","--samFlagInclude","sam-exclude","--samFlagExclude","min-fragment-length","--minFragmentLength","max-fragment-length","--maxFragmentLength","extend-reads","--extendReads").entrySet())if(options.containsKey(entry.getKey()))arguments.addAll(List.of(entry.getValue(),options.get(entry.getKey())));if(bool(options,"ignore-duplicates",false))arguments.add("--ignoreDuplicates");
        var labels=samples.stream().map(Sample::id).toList();arguments.add("--labels");arguments.addAll(labels);runtime.run("multiBamSummary",arguments,"bam-summary",timeout);size(directory.resolve("summary.npz"),maxBytes);size(directory.resolve("original-counts.tsv"),maxBytes);
        var request=audit("summary",runtime,directory.resolve("summary.npz"),reference,maxCells);request.put("labels",labels);request.put("raw",runtime.path(directory.resolve("original-counts.tsv")));request.put("table",runtime.path(directory.resolve("results.tsv")));request.put("bin_size",bin);request.put("step",step);if(canonical!=null)request.put("regions",runtime.path(canonical));var result=runtime.audit(request,"summary-audit",timeout);session.put("summary_audit",result.get("audit"));var model=baseModel("summary",options.get("genome-build"),labels);model.put("summary_audit",result.get("audit"));var members=new ArrayList<>(List.of("summary.npz","reference.sizes","samples.tsv","results.tsv","original-counts.tsv"));if(canonical!=null){members.add("regions/regions.bed");model.put("regions_file","regions/regions.bed");}sealModel(directory,model,members);
        warnings.add("BAM SUMMARY COUNT UNITS:original alignment-overlap counts,with the declared filters/extension. They are not library-normalized expression,base depth or a count of unique fragments unless that is separately established. Supplied BED6 windows can overlap and therefore reuse reads. NPZ/raw-coordinate/sample-label agreement is audited; no object arrays or pickle loading. Correlations depend on bin width,spacing,regions and zero-row policy; inspect those choices before interpreting sample similarity.");
    }
    private static void plot(DeepToolsRuntime runtime,Path directory,Map<String,String> options,String method,Map<Path,String> sources,long maxCells,long maxBytes,int timeout,Map<String,Object> session,List<String> warnings)throws Exception {
        Path marker=source(options.get("model"),sources,Math.min(maxBytes,64*1024*1024));var model=RegenieRuntime.object(marker);boolean correlation=method.equals("correlation");String kind=correlation?"summary":"matrix";if(!("jlinalg-deeptools-"+kind+"-v1").equals(model.get("schema"))||!"3.5.6".equals(model.get("upstream_version")))throw new IOException("Select the matching sealed "+kind+" model.json from this integration");
        Path home=marker.getParent();if(!(model.get("files") instanceof Map<?,?> files)||files.isEmpty())throw new IOException("Model lacks sealed members");for(var entry:files.entrySet()){Path member=RegenieRuntime.contained(home,String.valueOf(entry.getKey()));Path actual=source(member.toString(),sources,maxBytes);if(!hash(actual).equals(entry.getValue()))throw new IOException("Model member changed:"+member);}
        String matrixName=correlation?"summary.npz":"matrix.gz";for(String name:List.of(matrixName,"reference.sizes","samples.tsv","results.tsv"))if(!files.containsKey(name))throw new IOException("Model is missing required member:"+name);
        if(!(model.get("labels") instanceof List<?> labelValues)||labelValues.isEmpty()||labelValues.size()>1000||labelValues.stream().anyMatch(value->!(value instanceof String)))throw new IOException("Model sample labels must be a bounded nonempty list of exact strings");List<String> labels=labelValues.stream().map(String::valueOf).toList();for(String label:labels)id(label,"sample label");if(new HashSet<>(labels).size()!=labels.size())throw new IOException("Model sample labels repeat");
        if(!(model.get("genome_build") instanceof String build)||build.isBlank())throw new IOException("Model lacks its declared genome build");if(!correlation)id(String.valueOf(model.get("group_label")),"group label");
        var reference=GenomicSignalCli.reference(home.resolve("reference.sizes"),"sizes");String format=options.getOrDefault("format","png");Path figure=directory.resolve("figure."+format),input=home.resolve(matrixName);String dpi=Integer.toString(integer(options,"dpi",100,40,300));
        var arguments=new ArrayList<String>();
        if(correlation){var request=audit("correlation",runtime,input,reference,maxCells);request.put("labels",labels);request.put("method",options.get("correlation-method"));request.put("skip_zeros",options.get("zero-rows").equals("omit"));session.put("correlation_input_audit",runtime.audit(request,"correlation-input-audit",timeout).get("audit"));arguments.addAll(List.of("-in",runtime.path(input),"--corMethod",options.get("correlation-method"),"--whatToPlot",options.get("what-to-plot"),"-o",runtime.path(figure),"--outFileCorMatrix",runtime.path(directory.resolve("original-correlations.tsv")),"--colorMap",options.getOrDefault("color-map","viridis")));if(options.get("zero-rows").equals("omit"))arguments.add("--skipZeros");
            if(options.containsKey("plot-title"))arguments.addAll(List.of("--plotTitle",options.get("plot-title")));runtime.run("plotCorrelation",arguments,"plot-correlation",timeout);request.put("result",runtime.path(directory.resolve("original-correlations.tsv")));request.put("table",runtime.path(directory.resolve("results.tsv")));session.put("correlation_output_audit",runtime.audit(request,"correlation-output-audit",timeout).get("audit"));warnings.add("CORRELATION MODEL:method="+options.get("correlation-method")+",zero-rows="+options.get("zero-rows")+"; complete finite nonnegative BAM-summary rows only. Constant columns or fewer than two retained rows fail with sample-specific recovery. Actual four-decimal coefficients are checked against independent centered dot products or average tied ranks. Heatmap clustering can reorder samples; result rows retain actual labels. No outlier removal,library normalization,causal inference or automatic sample removal.");
        }else{
            String regionName=String.valueOf(model.get("regions_file"));if(!files.containsKey(regionName))throw new IOException("Model region contract is not sealed");Path regions=RegenieRuntime.contained(home,regionName);var request=matrixAudit(runtime,directory,model,input,regions,maxCells);session.put("matrix_input_audit",runtime.audit(request,"matrix-input-audit",timeout).get("audit"));
            arguments.addAll(List.of("-m",runtime.path(input),"-out",runtime.path(figure),"--dpi",dpi,"--regionsLabel",String.valueOf(model.get("group_label"))));if(options.containsKey("plot-title"))arguments.addAll(List.of("--plotTitle",options.get("plot-title")));if(bool(options,"per-group",false))arguments.add("--perGroup");
            if(method.equals("plot-profile")){arguments.addAll(List.of("--averageType",options.get("average"),"--plotType",options.getOrDefault("plot-type","lines"),"--outFileNameData",runtime.path(directory.resolve("profile-data.tsv"))));runtime.run("plotProfile",arguments,"plot-profile",timeout);request.put("profile_data",runtime.path(directory.resolve("profile-data.tsv")));request.put("average",options.get("average"));session.put("profile_data_audit",runtime.audit(request,"profile-data-audit",timeout).get("audit"));}
            else{arguments.addAll(List.of("--averageTypeSummaryPlot",options.get("average"),"--sortRegions",options.getOrDefault("sort-regions","keep"),"--sortUsing",options.getOrDefault("sort-using","mean"),"--colorMap",options.getOrDefault("color-map","viridis"),"--outFileSortedRegions",runtime.path(directory.resolve("plotted-regions.bed"))));runtime.run("plotHeatmap",arguments,"plot-heatmap",timeout);request.put("sorted_regions",runtime.path(directory.resolve("plotted-regions.bed")));request.put("sorted_keep",options.getOrDefault("sort-regions","keep").equals("keep"));session.put("plotted_region_audit",runtime.audit(request,"plotted-region-audit",timeout).get("audit"));}
            warnings.add("PROFILE/HEATMAP MODEL:sealed original computeMatrix data and exact sample/region/reference identities. Average="+options.get("average")+"; missing cells/omitted regions remain explicit in region-status.tsv and matrix audits. No refitting,renormalization or expression/count-model inference. Original exported profile data are checked against the declared matrix reduction. Heatmap ordering is explicit; keep-order preserves input matrix order. Color limits and clustering beyond the exposed options remain separate choices.");
        }
        var request=audit("figure",runtime,figure,reference,maxCells);request.put("format",format);request.put("max_bytes",maxBytes);var result=runtime.audit(request,"figure-audit",timeout);session.put("figure_audit",result.get("audit"));session.put("source_model_sha256",hash(marker));session.put("genome_build_declared",model.get("genome_build"));
        if(!correlation)table(directory.resolve("results.tsv"),List.of("figure","format","sample_count","source_model_sha256"),Collections.singletonList(new String[]{figure.getFileName().toString(),format,Integer.toString(labels.size()),hash(marker)}));
        if(!format.equals("png"))warnings.add("VECTOR EXPORT CHECK:PDF/SVG structure and completion are verified here; rendered-export validation is separate. Inspect the figure at publication size before sharing.");
    }
    private static Map<String,Object> matrixAudit(DeepToolsRuntime runtime,Path directory,Map<?,?> model,Path matrix,Path regions,long maxCells)throws IOException {var request=audit("matrix",runtime,matrix,Map.of(),maxCells);request.put("regions",runtime.path(regions));request.put("labels",model.get("labels"));request.put("columns",model.get("columns_per_sample"));request.put("group_label",model.get("group_label"));request.put("parameters",model.get("parameters"));request.put("missing",model.get("missing"));request.put("status_table",runtime.path(directory.resolve("region-status.tsv")));return request;}
    private static Map<String,Object> baseModel(String kind,String build,List<String> labels){var model=new LinkedHashMap<String,Object>();model.put("schema","jlinalg-deeptools-"+kind+"-v1");model.put("upstream_version","3.5.6");model.put("genome_build",build);model.put("labels",labels);return model;}
    private static void sealModel(Path directory,Map<String,Object> model,List<String> names)throws IOException {var files=new LinkedHashMap<String,String>();for(String name:names)files.put(name,hash(directory.resolve(name)));model.put("files",files);Files.writeString(directory.resolve("model.json"),RegenieRuntime.json(model)+"\n");}
    private static List<Sample> samples(Path manifest,Map<Path,String> sources,long limit)throws IOException {var result=new ArrayList<Sample>();var ids=new HashSet<String>();try(var reader=Files.newBufferedReader(manifest)){if(!"sample\tpath".equals(reader.readLine()))throw new IOException("Sample manifest requires exact unquoted sample/path TSV header");String line;while((line=reader.readLine())!=null){String[] fields=line.split("\t",-1);if(fields.length!=2)throw new IOException("Sample manifest requires two nonempty unquoted columns");id(fields[0],"sample ID");if(!ids.add(fields[0])||fields[1].isBlank())throw new IOException("Duplicate sample ID or empty path");Path path=Path.of(fields[1]);if(!path.isAbsolute())path=manifest.getParent().resolve(path);result.add(new Sample(fields[0],source(path.toString(),sources,limit)));if(result.size()>1000)throw new IOException("At most1000samples per explicit matrix contract");}}if(result.isEmpty())throw new IOException("Sample manifest is empty");return result;}
    private static int bed(Path path,Map<String,Long> reference)throws IOException {var ids=new HashSet<String>();int rows=0;try(var reader=Files.newBufferedReader(path)){String line;while((line=reader.readLine())!=null){if(line.isBlank())continue;if(line.startsWith("#"))throw new IOException("BED6 grouping/comment directives are not supported; supply one explicitly labelled group");String[] fields=line.split("\t",-1);if(fields.length!=6||!reference.containsKey(fields[0])||!Set.of("+","-").contains(fields[5]))throw new IOException("Require exact stranded BED6 rows on the explicit reference");long start=Long.parseLong(fields[1]),stop=Long.parseLong(fields[2]);double score=finite(fields[4],"BED score");if(start<0||stop<=start||stop>reference.get(fields[0])||score<0||score>1000||fields[3].isBlank()||fields[3].length()>256||fields[3].chars().anyMatch(Character::isWhitespace)||!ids.add(fields[3]))throw new IOException("Invalid bounds,score,whitespace or duplicate region identity");if(++rows>1_000_000)throw new IOException("BED exceeds1millionregions");}}if(rows==0)throw new IOException("No BED6 regions");return rows;}
    private static Path source(String name,Map<Path,String> sources,long limit)throws IOException {Path path=RnaToolRuntime.file(name);size(path,limit);String value=hash(path),previous=sources.putIfAbsent(path,value);if(previous!=null&&!previous.equals(value))throw new IOException("Source changed during preparation:"+path);return path;}
    private static void size(Path path,long max)throws IOException {if(!Files.isRegularFile(path)||Files.size(path)>max)throw new IOException("Missing file or max-bytes exceeded:"+path);}
    private static void indexes(Path input,Map<Path,String> sources,long limit)throws IOException {String name=input.toString();var paths=new LinkedHashSet<Path>(List.of(Path.of(name+".bai"),Path.of(name+".csi")));if(name.endsWith(".bam")){paths.add(Path.of(name.substring(0,name.length()-4)+".bai"));paths.add(Path.of(name.substring(0,name.length()-4)+".csi"));}boolean found=false;for(Path path:paths)if(Files.exists(path)){source(path.toString(),sources,limit);found=true;}if(!found)throw new IOException("BAM requires an existing adjacent BAI/CSI; sort/index the original first without overwriting inputs");}
    private static Map<String,Object> audit(String kind,DeepToolsRuntime runtime,Path input,Map<String,Long> reference,long maxCells)throws IOException {var request=new LinkedHashMap<String,Object>();request.put("schema","jlinalg-deeptools-audit-v1");request.put("kind",kind);request.put("input",runtime.path(input));request.put("reference",reference);request.put("max_cells",maxCells);return request;}
    private static int positive(Map<String,String> options,String name){required(options,name);return integer(options,name,1,1,Integer.MAX_VALUE);}
    private static int nonnegative(Map<String,String> options,String name){required(options,name);return integer(options,name,0,0,Integer.MAX_VALUE);}
    private static String choiceRequired(Map<String,String> options,String name,String... values)throws IOException {required(options,name);return choice(options,name,"",values);}
    private static String choice(Map<String,String> options,String name,String fallback,String... values)throws IOException {String value=options.getOrDefault(name,fallback);if(!Set.of(values).contains(value))throw new IOException(name+" requires "+String.join("/",values));return value;}
    private static void id(String value,String name)throws IOException {if(!value.matches("[A-Za-z0-9][A-Za-z0-9_.-]{0,127}"))throw new IOException(name+" requires a stable1..128character ASCII alphanumeric/dot/hyphen/underscore ID beginning alphanumeric");}
    private static void text(String value,String name,int length)throws IOException {if(value.length()>length||value.chars().anyMatch(character->character<32))throw new IOException(name+" must be single-line text within"+length+"characters");}
    private static List<String> warnings(Path directory)throws IOException {var result=new ArrayList<String>();try(var paths=Files.list(directory)){for(Path path:paths.filter(value->value.toString().endsWith(".log")).toList())try(var lines=Files.lines(path)){lines.filter(line->line.matches("(?i).*warning\\b.*")).limit(100).forEach(line->result.add(path.getFileName()+":"+line));}}return result;}
    static String help(){return """
        matrix: --samples MANIFEST.tsv(sample/path) --sizes EXACT.sizes --genome-build BUILD
          --regions STRANDED.bed6 --group-label ID --mode reference-point|scale-regions --bin-size BASES
          --upstream BASES --downstream BASES (exact bin multiples); reference-point requires
          --reference-point TSS|TES|center; scale-regions requires --body-length BASES.
          --missing zero|retain|error --skip-zero-rows true|false --bin-average mean|median|min|max|std|sum
          required. --nan-after-end false. Exact IDs/order,one explicitly labelled BED6 group.
          Produces matrix.gz,values.tsv,region statuses and sealed model.json for plotting.
        bam-summary: --samples MANIFEST.tsv --sizes EXACT.sizes --genome-build BUILD --mode bins|regions
          bins requires --bin-size BASES; optional --distance-between-bins 0. regions requires --regions BED6.
          Existing coordinate-sorted/indexed BAMs; --max-records 10000000; optional MAPQ,SAM flags,
          duplicate,fragment-length and explicit extension options as for bam-coverage. Raw alignment overlaps.
          Produces audited NPZ,coordinate-count results.tsv and sealed model.json for correlation.
        plot-profile|plot-heatmap: --model MATRIX_BUNDLE/model.json --average mean|median|min|max|std|sum
          --format png|pdf|svg --dpi 100 --per-group false --plot-title TEXT.
          profile: --plot-type lines|fill|se|std|overlapped_lines|heatmap; audited profile-data.tsv.
          heatmap: --sort-regions keep|ascend|descend --sort-using mean|median|min|max|sum|region_length
          --color-map viridis|plasma|magma|inferno|cividis|RdBu_r|Greys. Explicit ordered region export.
        correlation: --model SUMMARY_BUNDLE/model.json --correlation-method pearson|spearman
          --what-to-plot heatmap|scatterplot --zero-rows keep|omit required. --format png|pdf|svg.
          Constant columns/fewer than2retained rows fail; exact sample labels and independent coefficients audited.
        All: --runtime-home HOME or JLINALG_DEEPTOOLS_HOME --out NEW_DIR --timeout 3600(per stage)
          --max-cells 10000000 --max-bytes 268435456(output/model/track budget). No implicit normalization,
          pickle,installation or historical/full-paper parity. Missing runtime skips3; errors2 quarantine partials.
        """;}
}
